// Unicode data helpers needed to emulate CPython semantics.
//
// Three independent pieces live here:
//   1. The Python "unicode whitespace" set (the non-ASCII part), used by
//      int() 's decimal/space transform.
//   2. The Nd (decimal digit) block table, used to map a Unicode digit to its
//      numeric value the way Py_UNICODE_TODECIMAL does.
//   3. str.isprintable() emulation, used by Python's str repr().

// ---------------------------------------------------------------------------
// 1. Whitespace
// ---------------------------------------------------------------------------

// ASCII whitespace as recognised by the C level Py_ISSPACE() used inside
// PyLong_FromString.  Note that 0x1c..0x1f (FS/GS/RS/US) are *not* here even
// though str.isspace() considers them whitespace.
const ASCII_SPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

export function isAsciiSpace(cp) {
  return ASCII_SPACE.has(cp);
}

// Non-ASCII code points for which Py_UNICODE_ISSPACE() is true.
const NON_ASCII_SPACE = new Set([
  0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

// Py_UNICODE_ISSPACE for any code point.
export function isPyUnicodeSpace(cp) {
  if (cp < 128) return ASCII_SPACE.has(cp) || (cp >= 0x1c && cp <= 0x1f);
  return NON_ASCII_SPACE.has(cp);
}

// ---------------------------------------------------------------------------
// 2. Decimal digits (general category Nd)
// ---------------------------------------------------------------------------

// The code point of the DIGIT ZERO of every Nd block.  Every block is exactly
// ten consecutive code points, so the numeric value of a digit is
// `cp - blockZero`.  The table is hard-coded rather than derived from the
// runtime's \p{Nd} table so the port stays pinned to the reference's Unicode
// version.
const ND_ZEROS = [
  0x30, 0x660, 0x6f0, 0x7c0, 0x966, 0x9e6, 0xa66, 0xae6, 0xb66, 0xbe6,
  0xc66, 0xce6, 0xd66, 0xde6, 0xe50, 0xed0, 0xf20, 0x1040, 0x1090, 0x17e0,
  0x1810, 0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0, 0x1c40, 0x1c50,
  0xa620, 0xa8d0, 0xa900, 0xa9d0, 0xa9f0, 0xaa50, 0xabf0, 0xff10,
  0x104a0, 0x10d30, 0x11066, 0x110f0, 0x11136, 0x111d0, 0x112f0, 0x11450,
  0x114d0, 0x11650, 0x116c0, 0x11730, 0x118e0, 0x11950, 0x11c50, 0x11d50,
  0x11da0, 0x11f50, 0x16a60, 0x16ac0, 0x16b50, 0x1d7ce, 0x1d7d8, 0x1d7e2,
  0x1d7ec, 0x1d7f6, 0x1e140, 0x1e2f0, 0x1e4f0, 0x1e950, 0x1fbf0,
];

// ND_ZEROS is already ascending; keep a sorted copy so the binary search below
// is correct even if the literal above is ever reordered.
const ND_SORTED = ND_ZEROS.slice().sort((x, y) => x - y);

// Numeric value 0..9 of a Unicode decimal digit, or -1 when `cp` is not Nd.
export function ndValue(cp) {
  let lo = 0;
  let hi = ND_SORTED.length - 1;
  let best = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (ND_SORTED[mid] <= cp) {
      best = ND_SORTED[mid];
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (best < 0) return -1;
  const v = cp - best;
  return v >= 0 && v <= 9 ? v : -1;
}

// ---------------------------------------------------------------------------
// 3. str.isprintable()
// ---------------------------------------------------------------------------

// Python: a character is non-printable when its general category is one of
// "Other" (C*) or "Separator" (Z*), except for the ASCII space U+0020.
const NON_PRINTABLE_RE = /[\p{C}\p{Z}]/u;

export function isPrintableCodePoint(cp) {
  if (cp === 0x20) return true;
  if (cp >= 0xd800 && cp <= 0xdfff) return false; // lone surrogates: category Cs
  return !NON_PRINTABLE_RE.test(String.fromCodePoint(cp));
}

// "Byte string" helpers.
//
// A byte string is represented as a plain JavaScript string whose every UTF-16
// code unit is in the range 0..255 (a latin-1 string).  All byte level work in
// this port goes through String / charCodeAt / fromCharCode.

import { PyUnicodeEncodeError } from './errors.mjs';

// Iterate a JS string by Unicode code point (surrogate pairs count as one),
// mirroring how CPython indexes str objects.
export function codePoints(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff && i + 1 < text.length) {
      const next = text.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        out.push((unit - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000);
        i += 1;
        continue;
      }
    }
    out.push(unit);
  }
  return out;
}

// Number of bytes in a byte string.  Every code unit is one byte, so this is
// just the length; kept as a named helper because bencode's length prefix is
// specified as a byte count.
export function byteLength(bytes) {
  return bytes.length;
}

export function byteAt(bytes, index) {
  return bytes.charCodeAt(index);
}

export function fromByteValues(values) {
  let out = '';
  for (let i = 0; i < values.length; i += 1) out += String.fromCharCode(values[i]);
  return out;
}

// Emulation of Python's str.encode('ascii') with the default 'strict' error
// handler.  Returns a byte string; raises PyUnicodeEncodeError carrying the
// first maximal run of non-ASCII code points.
export function encodeAscii(text) {
  const cps = codePoints(text);
  for (let i = 0; i < cps.length; i += 1) {
    if (cps[i] >= 0x80) {
      let end = i + 1;
      while (end < cps.length && cps[end] >= 0x80) end += 1;
      throw new PyUnicodeEncodeError('ascii', cps[i], i, end);
    }
  }
  // Every code point is < 0x80, so the byte string equals the input string.
  let out = '';
  for (let i = 0; i < cps.length; i += 1) out += String.fromCharCode(cps[i]);
  return out;
}

// Error types raised by the Python-emulating layers plus the PyInstaller-style
// traceback renderer used for uncaught exceptions.

// Raised by pyInt() -- the analogue of Python's ValueError.
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyValueError';
  }
}

// Raised by encodeAscii().  `start` and `end` delimit the offending run of
// code points (end is exclusive, exactly like CPython's UnicodeEncodeError).
export class PyUnicodeEncodeError extends Error {
  constructor(encoding, codePoint, start, end) {
    super('unicode encode error');
    this.name = 'PyUnicodeEncodeError';
    this.encoding = encoding;
    this.codePoint = codePoint;
    this.start = start;
    this.end = end;
  }

  // CPython renders the offending character with a \x / \u / \U escape whose
  // hex digits are lowercase and zero padded.
  escapedChar() {
    const cp = this.codePoint;
    const hex = cp.toString(16);
    if (cp <= 0xff) return '\\x' + hex.padStart(2, '0');
    if (cp <= 0xffff) return '\\u' + hex.padStart(4, '0');
    return '\\U' + hex.padStart(8, '0');
  }

  // str(exc) for a UnicodeEncodeError.
  toPythonString() {
    if (this.end - this.start === 1) {
      return (
        "'" + this.encoding + "' codec can't encode character '" +
        this.escapedChar() + "' in position " + this.start +
        ': ordinal not in range(128)'
      );
    }
    return (
      "'" + this.encoding + "' codec can't encode characters in position " +
      this.start + '-' + (this.end - 1) + ': ordinal not in range(128)'
    );
  }
}

// Signals that the program should terminate with the given status.  Any text
// already produced is written by the caller.
export class SystemExit extends Error {
  constructor(status) {
    super('system exit ' + status);
    this.name = 'SystemExit';
    this.status = status;
  }
}

const SCRIPT_FILE = 'test12.py';
const SCRIPT_NAME = 'test12';

// The frozen (PyInstaller) build has no source available, so the traceback
// shows the File/line header with no source line and no caret underline.
export function renderTraceback(lineNumber, exceptionName, exceptionMessage, pid) {
  return (
    'Traceback (most recent call last):\n' +
    '  File "' + SCRIPT_FILE + '", line ' + lineNumber + ', in <module>\n' +
    exceptionName + ': ' + exceptionMessage + '\n' +
    '[PYI-' + pid + ':ERROR] Failed to execute script ' +
    "'" + SCRIPT_NAME + "' due to unhandled exception!\n"
  );
}

// The Python object model pieces this program needs.
//
//   bytes  -> PyBytes wrapping a latin-1 byte string
//   int    -> BigInt (Python ints are unbounded)
//   list   -> Array
//   dict   -> PyDict, an insertion-ordered mapping from byte string keys to
//             values (Python dicts preserve insertion order)

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes;
  }
}

export function bytesOf(byteString) {
  return new PyBytes(byteString);
}

export class PyDict {
  constructor(entries) {
    // entries: array of [latin-1 key byte string, value]
    this.entries = entries ? entries.slice() : [];
  }

  set(keyBytes, value) {
    for (let i = 0; i < this.entries.length; i += 1) {
      if (this.entries[i][0] === keyBytes) {
        this.entries[i][1] = value;
        return;
      }
    }
    this.entries.push([keyBytes, value]);
  }

  // Entries ordered by raw unsigned-byte lexicographic key order.  Because
  // every key code unit is 0..255, the default string comparison is exactly
  // an unsigned bytewise comparison.
  sortedEntries() {
    return this.entries.slice().sort((x, y) => {
      if (x[0] < y[0]) return -1;
      if (x[0] > y[0]) return 1;
      return 0;
    });
  }
}

// Emulation of Python's repr() for the value types this program prints.

import { PyBytes, PyDict } from './pyvalues.mjs';
import { codePoints } from './bytes.mjs';
import { isPrintableCodePoint } from './unidata.mjs';

const SQ = 0x27; // '
const DQ = 0x22; // "
const BACKSLASH = 0x5c;

function hex2(value) {
  return value.toString(16).padStart(2, '0');
}

// Python picks ' unless the value contains ' and does not contain ".  The
// decision needs the whole value, so repr is necessarily a two-pass encoder.
function chooseQuote(codeUnits) {
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < codeUnits.length; i += 1) {
    if (codeUnits[i] === SQ) hasSingle = true;
    else if (codeUnits[i] === DQ) hasDouble = true;
  }
  return hasSingle && !hasDouble ? DQ : SQ;
}

// repr() of a bytes object.  `byteString` is a latin-1 byte string.
export function reprBytes(byteString) {
  const units = [];
  for (let i = 0; i < byteString.length; i += 1) units.push(byteString.charCodeAt(i));
  const quote = chooseQuote(units);
  const q = String.fromCharCode(quote);

  let body = '';
  for (let i = 0; i < units.length; i += 1) {
    const c = units[i];
    if (c === quote || c === BACKSLASH) {
      body += '\\' + String.fromCharCode(c);
    } else if (c === 0x09) {
      body += '\\t';
    } else if (c === 0x0a) {
      body += '\\n';
    } else if (c === 0x0d) {
      body += '\\r';
    } else if (c < 0x20 || c >= 0x7f) {
      body += '\\x' + hex2(c);
    } else {
      body += String.fromCharCode(c);
    }
  }
  return 'b' + q + body + q;
}

// repr() of a str object.
export function reprStr(text) {
  const units = [];
  for (let i = 0; i < text.length; i += 1) units.push(text.charCodeAt(i));
  const quote = chooseQuote(units);
  const q = String.fromCharCode(quote);

  let body = '';
  const cps = codePoints(text);
  for (let i = 0; i < cps.length; i += 1) {
    const cp = cps[i];
    if (cp === quote || cp === BACKSLASH) {
      body += '\\' + String.fromCharCode(cp);
    } else if (cp === 0x09) {
      body += '\\t';
    } else if (cp === 0x0a) {
      body += '\\n';
    } else if (cp === 0x0d) {
      body += '\\r';
    } else if (cp < 0x20 || cp === 0x7f) {
      body += '\\x' + hex2(cp);
    } else if (cp < 0x7f) {
      body += String.fromCharCode(cp);
    } else if (isPrintableCodePoint(cp)) {
      body += String.fromCodePoint(cp);
    } else if (cp <= 0xff) {
      body += '\\x' + hex2(cp);
    } else if (cp <= 0xffff) {
      body += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      body += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return q + body + q;
}

// repr() of an int.  Canonical base 10, '-' only for negatives, no '+', no
// separators, no leading zeros, arbitrary precision.
export function reprInt(value) {
  return value.toString();
}

// repr() of any value this program can produce.
export function reprValue(value) {
  if (value instanceof PyBytes) return reprBytes(value.bytes);
  if (typeof value === 'bigint') return reprInt(value);
  if (Array.isArray(value)) return reprList(value);
  if (value instanceof PyDict) return reprDict(value);
  throw new Error('unreprable value');
}

export function reprList(items) {
  const parts = [];
  for (let i = 0; i < items.length; i += 1) parts.push(reprValue(items[i]));
  return '[' + parts.join(', ') + ']';
}

// Dicts print in insertion order; the decoder inserts in wire order, which is
// the encoder's sorted order.
export function reprDict(dict) {
  const parts = [];
  for (let i = 0; i < dict.entries.length; i += 1) {
    const entry = dict.entries[i];
    parts.push(reprBytes(entry[0]) + ': ' + reprValue(entry[1]));
  }
  return '{' + parts.join(', ') + '}';
}

// Hand-written bencode encoder / decoder operating on latin-1 byte strings.
//
// Grammar:
//   bytes -> <byteLength> ":" <raw bytes>
//   int   -> "i" <canonical decimal> "e"
//   list  -> "l" <value>* "e"
//   dict  -> "d" ( <bytes key> <value> )* "e"    keys sorted bytewise
//
// There is no escaping and there are no separators anywhere: payload bytes are
// emitted verbatim even when they look like structure.

import { PyBytes, PyDict } from './pyvalues.mjs';
import { byteLength } from './bytes.mjs';

export function encode(value) {
  if (value instanceof PyBytes) return encodeBytes(value.bytes);
  if (typeof value === 'bigint') return encodeInt(value);
  if (Array.isArray(value)) return encodeList(value);
  if (value instanceof PyDict) return encodeDict(value);
  throw new Error('cannot bencode value');
}

export function encodeBytes(byteString) {
  return String(byteLength(byteString)) + ':' + byteString;
}

export function encodeInt(value) {
  return 'i' + value.toString() + 'e';
}

export function encodeList(items) {
  let out = 'l';
  for (let i = 0; i < items.length; i += 1) out += encode(items[i]);
  return out + 'e';
}

export function encodeDict(dict) {
  const entries = dict.sortedEntries();
  let out = 'd';
  for (let i = 0; i < entries.length; i += 1) {
    out += encodeBytes(entries[i][0]);
    out += encode(entries[i][1]);
  }
  return out + 'e';
}

// ---------------------------------------------------------------------------
// Decoder
// ---------------------------------------------------------------------------

const ZERO = 0x30;
const NINE = 0x39;

function isDigit(code) {
  return code >= ZERO && code <= NINE;
}

export function decode(byteString) {
  const state = { data: byteString, pos: 0 };
  const value = decodeValue(state);
  return value;
}

function decodeValue(state) {
  const c = state.data.charCodeAt(state.pos);
  if (c === 0x69) return decodeInt(state); // 'i'
  if (c === 0x6c) return decodeList(state); // 'l'
  if (c === 0x64) return decodeDict(state); // 'd'
  if (isDigit(c)) return new PyBytes(decodeByteString(state));
  throw new Error('malformed bencode at offset ' + state.pos);
}

function decodeInt(state) {
  // Stop at the FIRST 'e' after the digits.
  state.pos += 1; // skip 'i'
  let text = '';
  if (state.data.charCodeAt(state.pos) === 0x2d) {
    text += '-';
    state.pos += 1;
  }
  while (state.pos < state.data.length && isDigit(state.data.charCodeAt(state.pos))) {
    text += state.data.charAt(state.pos);
    state.pos += 1;
  }
  if (state.data.charCodeAt(state.pos) !== 0x65) {
    throw new Error('malformed bencode integer');
  }
  state.pos += 1; // skip 'e'
  return BigInt(text);
}

function decodeByteString(state) {
  let lengthText = '';
  while (state.pos < state.data.length && isDigit(state.data.charCodeAt(state.pos))) {
    lengthText += state.data.charAt(state.pos);
    state.pos += 1;
  }
  if (state.data.charCodeAt(state.pos) !== 0x3a) {
    throw new Error('malformed bencode byte string');
  }
  state.pos += 1; // skip ':'
  // The payload is sliced by the declared length; never by searching for a
  // delimiter, because payloads legitimately contain ':' and 'e'.
  const count = Number(lengthText);
  const payload = state.data.slice(state.pos, state.pos + count);
  state.pos += count;
  return payload;
}

function decodeList(state) {
  state.pos += 1; // skip 'l'
  const items = [];
  while (state.data.charCodeAt(state.pos) !== 0x65) {
    items.push(decodeValue(state));
  }
  state.pos += 1; // skip 'e'
  return items;
}

function decodeDict(state) {
  state.pos += 1; // skip 'd'
  const dict = new PyDict();
  // Insert in wire order so that the dict's iteration order matches the
  // encoder's sorted key order.
  while (state.data.charCodeAt(state.pos) !== 0x65) {
    const key = decodeByteString(state);
    const value = decodeValue(state);
    dict.set(key, value);
  }
  state.pos += 1; // skip 'e'
  return dict;
}

// Emulation of CPython's int(str) for base 10.
//
// CPython does this in two phases:
//   1. _PyUnicode_TransformDecimalAndSpaceToASCII folds Unicode whitespace to
//      an ASCII space and Unicode Nd digits to the matching ASCII digit,
//      copying everything below U+007F verbatim.
//   2. PyLong_FromString then parses the resulting ASCII text strictly.
//
// Doing it in one regex pass over the raw string does not work: it is the
// verbatim copy in phase 1 that makes e.g. '\x1c' (str.isspace() == True) a
// rejected input.

import { PyValueError } from './errors.mjs';
import { codePoints } from './bytes.mjs';
import { isPyUnicodeSpace, ndValue } from './unidata.mjs';

// Phase 1.
export function transformDecimalAndSpaceToAscii(text) {
  const cps = codePoints(text);
  let out = '';
  for (let i = 0; i < cps.length; i += 1) {
    const cp = cps[i];
    if (cp < 127) {
      out += String.fromCharCode(cp);
      continue;
    }
    if (isPyUnicodeSpace(cp)) {
      out += ' ';
      continue;
    }
    const digit = ndValue(cp);
    if (digit >= 0) {
      out += String.fromCharCode(0x30 + digit);
      continue;
    }
    // Anything else is left in place so that phase 2 is guaranteed to fail.
    out += String.fromCodePoint(cp);
  }
  return out;
}

// Phase 2.  ASCII whitespace here is exactly 0x09 0x0a 0x0b 0x0c 0x0d 0x20 --
// deliberately not JS's \s (which also strips U+FEFF and skips U+0085) and not
// String.prototype.trim().
const INT_RE = /^[\t\n\v\f\r ]*([+-]?)([0-9](?:_?[0-9])*)[\t\n\v\f\r ]*$/;

// int(text) -> BigInt.  Throws PyValueError when the text is not a valid int.
export function pyInt(text) {
  const ascii = transformDecimalAndSpaceToAscii(text);
  const match = INT_RE.exec(ascii);
  if (match === null) {
    throw new PyValueError('invalid literal for int() with base 10');
  }
  const sign = match[1] === '-' ? '-' : '';
  const digits = match[2].split('_').join('');
  return BigInt(sign + digits);
}

// A minimal but faithful clone of the slice of argparse this program uses.
//
// The structure deliberately mirrors CPython's argparse internals
// (_parse_optional / _get_option_tuples / _parse_known_args / consume_optional)
// because the observable error ordering falls out of that structure.

import { reprStr } from './pyrepr.mjs';
import { pyInt } from './pyint.mjs';
import { PyValueError, SystemExit } from './errors.mjs';

// The reference binary derives prog from basename(argv[0]); the port pins it so
// that every usage and error line stays byte identical.
export const PROG = 'test12_executable';

export const USAGE_LINE = 'usage: ' + PROG + ' [-h] --a A --b B --c C\n';

export const HELP_TEXT =
  USAGE_LINE +
  '\n' +
  'options:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n' +
  '  --b B\n' +
  '  --c C\n';

const PREFIX_CHARS = '-';

// Raised for the ArgumentError family; the parser turns these into
// "argument <name>: <message>".
export class ArgumentError extends Error {
  constructor(actionName, message) {
    super(message);
    this.name = 'ArgumentError';
    this.actionName = actionName;
    this.pyMessage = message;
  }

  toPythonString() {
    if (this.actionName === null || this.actionName === undefined) return this.pyMessage;
    return 'argument ' + this.actionName + ': ' + this.pyMessage;
  }
}

// Python's argparse negative-number matcher.  `\d` in a str pattern matches any
// Unicode decimal digit, and Python's `$` also matches before a single trailing
// newline -- both reproduced here.
const NEGATIVE_NUMBER_RE = /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

function actionName(action) {
  return action.names.join('/');
}

export function buildParser() {
  const help = { names: ['-h', '--help'], dest: null, nargs: 0, kind: 'help', required: false };
  const a = { names: ['--a'], dest: 'a', nargs: 1, kind: 'store', type: 'str', required: true };
  const b = { names: ['--b'], dest: 'b', nargs: 1, kind: 'store', type: 'str', required: true };
  const c = { names: ['--c'], dest: 'c', nargs: 1, kind: 'store', type: 'int', required: true };

  const actions = [help, a, b, c];
  // Insertion order matters: it drives both the ambiguous-option match list and
  // the required-arguments list.
  const optionStringActions = new Map();
  for (const action of actions) {
    for (const name of action.names) optionStringActions.set(name, action);
  }
  return { actions, optionStringActions };
}

// ---------------------------------------------------------------------------

class Parser {
  constructor(io) {
    const built = buildParser();
    this.actions = built.actions;
    this.optionStringActions = built.optionStringActions;
    this.io = io;
  }

  error(message) {
    this.io.stderr(USAGE_LINE);
    this.io.stderr(PROG + ': error: ' + message + '\n');
    throw new SystemExit(2);
  }

  printHelp() {
    this.io.stdout(HELP_TEXT);
    throw new SystemExit(0);
  }

  // ---- token classification ------------------------------------------------

  getOptionTuples(argString) {
    const result = [];
    const first = argString.charAt(0);
    const second = argString.charAt(1);
    if (PREFIX_CHARS.includes(first) && PREFIX_CHARS.includes(second)) {
      // Long options are only ever split at the '='.
      let prefix = argString;
      let sep = null;
      let explicitArg = null;
      const eq = argString.indexOf('=');
      if (eq >= 0) {
        prefix = argString.slice(0, eq);
        sep = '=';
        explicitArg = argString.slice(eq + 1);
      }
      for (const [name, action] of this.optionStringActions) {
        if (name.startsWith(prefix)) {
          result.push({ action, optionString: name, sep, explicitArg });
        }
      }
    } else if (PREFIX_CHARS.includes(first) && !PREFIX_CHARS.includes(second)) {
      // Single character options may be concatenated with their argument.
      const shortPrefix = argString.slice(0, 2);
      const shortExplicit = argString.slice(2);
      for (const [name, action] of this.optionStringActions) {
        if (name === shortPrefix) {
          result.push({ action, optionString: name, sep: '', explicitArg: shortExplicit });
        } else if (name.startsWith(argString)) {
          result.push({ action, optionString: name, sep: null, explicitArg: null });
        }
      }
    }
    return result;
  }

  parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString.charAt(0))) return null;

    if (this.optionStringActions.has(argString)) {
      return {
        action: this.optionStringActions.get(argString),
        optionString: argString,
        sep: null,
        explicitArg: null,
      };
    }
    if (argString.length === 1) return null;

    const eq = argString.indexOf('=');
    if (eq >= 0) {
      const head = argString.slice(0, eq);
      const value = argString.slice(eq + 1);
      if (this.optionStringActions.has(head)) {
        return {
          action: this.optionStringActions.get(head),
          optionString: head,
          sep: '=',
          explicitArg: value,
        };
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((t) => t.optionString).join(', ');
      this.error('ambiguous option: ' + argString + ' could match ' + matches);
    }
    if (tuples.length === 1) return tuples[0];

    // No numeric-looking option strings are registered, so anything that looks
    // like a negative number is a value, not an option.
    if (NEGATIVE_NUMBER_RE.test(argString)) return null;
    if (argString.includes(' ')) return null;

    // Option-like but unknown: it can never be consumed as a value.
    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  // ---- argument-count matching --------------------------------------------

  // For optionals the nargs pattern has all '-' handling stripped, so nargs=1
  // means "the very next token must be classified as a value" and nargs=0
  // always matches zero tokens.
  matchArgument(action, patternText) {
    if (action.nargs === 0) return 0;
    if (patternText.charAt(0) === 'A') return 1;
    throw new ArgumentError(actionName(action), 'expected one argument');
  }

  // ---- value conversion ----------------------------------------------------

  getValue(action, argString) {
    if (action.type === 'int') {
      try {
        return pyInt(argString);
      } catch (err) {
        if (err instanceof PyValueError) {
          throw new ArgumentError(
            actionName(action),
            'invalid int value: ' + reprStr(argString),
          );
        }
        throw err;
      }
    }
    return argString;
  }

  getValues(action, argStrings) {
    if (argStrings.length === 1 && action.nargs === 1) {
      return this.getValue(action, argStrings[0]);
    }
    return argStrings.map((s) => this.getValue(action, s));
  }

  // ---- main loop -----------------------------------------------------------

  parseKnownArgs(argStrings) {
    const namespace = { a: null, b: null, c: null };
    const seenActions = new Set();
    const extras = [];

    // Pre-pass: classify every token before any action runs.  An ambiguous
    // option is reported from here, which is why it outranks every other error.
    const pattern = [];
    const optionTuples = new Map();
    let i = 0;
    while (i < argStrings.length) {
      const s = argStrings[i];
      if (s === '--') {
        pattern.push('-');
        i += 1;
        while (i < argStrings.length) {
          pattern.push('A');
          i += 1;
        }
        break;
      }
      const tuple = this.parseOptional(s);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
      i += 1;
    }
    const patternText = pattern.join('');

    const takeAction = (action, values, optionString) => {
      seenActions.add(action);
      const converted = this.getValues(action, values);
      if (action.kind === 'help') {
        this.printHelp();
      } else {
        namespace[action.dest] = converted;
      }
    };

    const consumeOptional = (startIndex) => {
      let { action, optionString, sep, explicitArg } = optionTuples.get(startIndex);
      const argString = argStrings[startIndex];
      const actionTuples = [];
      let stop = startIndex + 1;

      for (;;) {
        if (action === null) {
          extras.push(argString);
          return startIndex + 1;
        }

        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this.matchArgument(action, 'A');

          if (
            argCount === 0 &&
            !PREFIX_CHARS.includes(optionString.charAt(1)) &&
            explicitArg !== ''
          ) {
            if (sep || PREFIX_CHARS.includes(explicitArg.charAt(0))) {
              throw new ArgumentError(
                actionName(action),
                'ignored explicit argument ' + reprStr(explicitArg),
              );
            }
            // Keep peeling single-dash flags out of the tail (-hh, -hx, ...).
            actionTuples.push([action, [], optionString]);
            const char = optionString.charAt(0);
            optionString = char + explicitArg.charAt(0);
            if (this.optionStringActions.has(optionString)) {
              action = this.optionStringActions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg.charAt(0) === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              actionName(action),
              'ignored explicit argument ' + reprStr(explicitArg),
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = this.matchArgument(action, patternText.slice(start));
          stop = start + argCount;
          const args = argStrings.slice(start, stop);
          actionTuples.push([action, args, optionString]);
          break;
        }
      }

      for (const [act, args, optStr] of actionTuples) takeAction(act, args, optStr);
      return stop;
    };

    const optionIndices = Array.from(optionTuples.keys()).sort((x, y) => x - y);
    const maxOptionIndex = optionIndices.length
      ? optionIndices[optionIndices.length - 1]
      : -1;

    let startIndex = 0;
    while (startIndex <= maxOptionIndex) {
      let nextOptionIndex = -1;
      for (const index of optionIndices) {
        if (index >= startIndex) {
          nextOptionIndex = index;
          break;
        }
      }
      if (nextOptionIndex < 0) break;
      if (startIndex !== nextOptionIndex) {
        // There are no positional actions, so nothing between here and the next
        // option can be consumed; it all becomes extras.
        for (let k = startIndex; k < nextOptionIndex; k += 1) extras.push(argStrings[k]);
        startIndex = nextOptionIndex;
      }
      startIndex = consumeOptional(nextOptionIndex);
    }
    for (let k = startIndex; k < argStrings.length; k += 1) extras.push(argStrings[k]);

    // Required arguments are reported before unrecognized ones.
    const missing = [];
    for (const action of this.actions) {
      if (action.required && !seenActions.has(action)) missing.push(actionName(action));
    }
    if (missing.length) {
      this.error('the following arguments are required: ' + missing.join(', '));
    }

    return { namespace, extras };
  }

  parseArgs(argStrings) {
    let result;
    try {
      result = this.parseKnownArgs(argStrings);
    } catch (err) {
      if (err instanceof ArgumentError) {
        this.error(err.toPythonString());
      }
      throw err;
    }
    if (result.extras.length) {
      this.error('unrecognized arguments: ' + result.extras.join(' '));
    }
    return result.namespace;
  }
}

export function parseArgs(argStrings, io) {
  return new Parser(io).parseArgs(argStrings);
}

