//   12  combined = [dict1, dict2]
//   13  encoded = bencoder.encode(combined)
//   14  decoded = bencoder.decode(encoded)
//   15  encoded_dict1 = bencoder.encode(dict1)
//   16  encoded_dict2 = bencoder.encode(dict2)
//   17  print(encoded)
//   18  print(decoded)
//   19  print(encoded_dict1)
//   20  print(encoded_dict2)

import { parseArgs } from './lib/argparse.mjs';
import { encodeAscii } from './lib/bytes.mjs';
import { PyBytes, PyDict } from './lib/pyvalues.mjs';
import { encode, decode } from './lib/bencode.mjs';
import { reprBytes, reprValue } from './lib/pyrepr.mjs';
import { PyUnicodeEncodeError, SystemExit, renderTraceback } from './lib/errors.mjs';

function atLine(lineNumber, fn) {
  try {
    return fn();
  } catch (err) {
    if (err instanceof PyUnicodeEncodeError) err.pyLine = lineNumber;
    throw err;
  }
}

export function run(argv, io, pid) {
  try {
    const args = parseArgs(argv, io);

    const dict1 = atLine(10, () => new PyDict([['first', new PyBytes(encodeAscii(args.a))]]));
    const dict2 = atLine(11, () => {
      const d = new PyDict();
      d.set('second', new PyBytes(encodeAscii(args.b)));
      d.set('number', args.c);
      return d;
    });

    const combined = [dict1, dict2];
    const encoded = encode(combined);
    const decoded = decode(encoded);
    const encodedDict1 = encode(dict1);
    const encodedDict2 = encode(dict2);

    io.stdout(reprBytes(encoded) + '\n');
    io.stdout(reprValue(decoded) + '\n');
    io.stdout(reprBytes(encodedDict1) + '\n');
    io.stdout(reprBytes(encodedDict2) + '\n');
    return 0;
  } catch (err) {
    if (err instanceof SystemExit) return err.status;
    if (err instanceof PyUnicodeEncodeError) {
      io.stderr(
        renderTraceback(err.pyLine, 'UnicodeEncodeError', err.toPythonString(), pid),
      );
      return 1;
    }
    throw err;
  }
}

const outChunks = [];
const errChunks = [];
const io = {
  stdout(text) {
    outChunks.push(text);
  },
  stderr(text) {
    errChunks.push(text);
  },
};

const status = run(process.argv.slice(2), io, process.pid);
if (outChunks.length) process.stdout.write(outChunks.join(''));
if (errChunks.length) process.stderr.write(errChunks.join(''));
process.exitCode = status;

