import { spawnSync } from 'node:child_process';

let seed = 987654321;
function rnd(n) { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; }

const asciiPool = [];
for (let c = 1; c < 128; c++) asciiPool.push(String.fromCharCode(c));

const uniCps = [0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c, 0x85, 0xa0, 0x1680, 0x2000, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0x200b, 0x2060, 0x180e, 0xfeff,
  0x660, 0x661, 0x662, 0x663, 0x6f9, 0x966, 0x66b, 0xff11, 0xff12,
  0x1d7cf, 0x1d7d8, 0xb2, 0xbd, 0x216b, 0x2460, 0x10a40, 0x4e00,
  0xff0b, 0xff0d, 0x2212, 0xff3f, 0xe9, 0x4e2d, 0x1f600, 0xad, 0x1e5f7, 0x10d47];
const uniPool = uniCps.map((c) => String.fromCodePoint(c));

function randVal(pool, maxLen) {
  let s = '';
  const n = rnd(maxLen);
  for (let i = 0; i < n; i++) s += pool[rnd(pool.length)];
  return s;
}

const norm = (s) => s.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
let pass = 0; let fail = 0;
const cases = [];
for (let i = 0; i < 170; i++) {
  cases.push(['--a', randVal(asciiPool, 8), '--b', randVal(asciiPool, 8),
    '--c', randVal(asciiPool.concat(uniPool), 6)]);
}
for (let i = 0; i < 60; i++) {
  cases.push(['--a', randVal(asciiPool.concat(uniPool), 5),
    '--b', randVal(asciiPool.concat(uniPool), 5), '--c', '1']);
}
for (const argv of cases) {
  const r = spawnSync('/workspace/dataset/test12_executable', argv, { encoding: 'latin1' });
  const p = spawnSync('node', ['/output/test12.mjs', ...argv], { encoding: 'latin1' });
  if (r.stdout === p.stdout && norm(r.stderr) === norm(p.stderr) && r.status === p.status) pass++;
  else {
    fail++;
    if (fail < 6) {
      console.log('FAIL', JSON.stringify(argv));
      console.log(' ref', r.status, JSON.stringify(r.stdout), JSON.stringify(norm(r.stderr)));
      console.log(' prt', p.status, JSON.stringify(p.stdout), JSON.stringify(norm(p.stderr)));
    }
  }
}
console.log('pass', pass, 'fail', fail);
